// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(
            address(this),
            IERC20(address(0)),
            ICVXBooster(address(0)),
            new address[](0)
        );
    }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        // transfer ownership to a fuzzed non-zero, non-deployer address
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // The reference returns newOwner, the bug returns address(0).
        // The general rule: owner() == newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

