import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable originalOwner = address(this);

    function setUp() public {
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0));
    }

    function testFuzz_property(address caller) public {
        // The original owner is set to address(this) in setUp.
        // The reference owner() always returns the stored owner (originalOwner),
        // regardless of caller.
        // The mutant returns msg.sender (caller).
        // For any caller != originalOwner, the mutant returns caller, which differs
        // from originalOwner.
        vm.prank(caller);
        address returned = c.owner();
        assertTrue(returned == originalOwner);
    }
}

