pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address caller) public {
        // Admissible domain: caller is not the deployer used in setUp
        vm.assume(caller != address(this));

        // The bug makes owner() return address(this), so even a random caller can call onlyOwner functions.
        // We check by calling renounceOwnership() (an onlyOwner function) from an unauthorized caller.
        bool success;
        vm.prank(caller);
        try c.renounceOwnership() {
            success = true;
        } catch {
            success = false;
        }

        // Reference: onlyOwner modifier should protect this, so success must be false for unauthorized caller.
        // Bug: owner() returns address(this), making _checkOwner() pass for any caller, so success becomes true.
        assertTrue(!success);
    }
}

